const ldap = require('ldapjs');
const { authenticate } = require('./authService');

// LDAP client setup
const client = ldap.createClient({
  url: 'ldap://localhost:389',
  bindDN: 'cn=admin,dc=example,dc=com',
  bindCredentials: 'admin_password'
});

// User login handler
async function loginHandler(req, res) {
  const { username, password } = req.body;

  // Input validation: restrict allowed characters
  if (!/^[a-zA-Z0-9_]{1,32}$/.test(username)) {
    return res.status(400).json({ error: 'Invalid username format' });
  }

  // Validate password is non-empty string
  if (typeof password !== 'string' || password.length === 0 || password.length > 128) {
    return res.status(400).json({ error: 'Invalid password' });
  }

  try {
    // Authenticate user against LDAP with parameterized query
    // Using LdapTemplate-style filter with placeholder binding
    const searchOptions = {
      filter: '(&(objectClass=person)(uid={0}))',
      scope: 'sub',
      attributes: ['uid', 'displayName']
    };

    const bindDN = `uid=${username},ou=users,dc=example,dc=com`;

    // First: bind as the user to verify credentials
    await client.bind(bindDN, password);

    // Second: search for user details using parameterized filter
    // The {0} placeholder is replaced with a properly escaped value
    const searchResult = await client.search('dc=example,dc=com', {
      ...searchOptions,
      filter: searchOptions.filter.replace('{0}', escapeFilterValue(username))
    });

    // Process search results
    const users = [];
    await new Promise((resolve, reject) => {
      searchResult.on('searchEntry', (entry) => {
        users.push({
          uid: entry.object.uid,
          displayName: entry.object.displayName
        });
      });
      searchResult.on('end', resolve);
      searchResult.on('error', reject);
    });

    if (users.length === 0) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Successful authentication
    res.json({ success: true, user: users[0] });
  } catch (err) {
    res.status(401).json({ error: 'Authentication failed' });
  } finally {
    client.unbind();
  }
}

// Helper function to escape LDAP filter special characters
function escapeFilterValue(value) {
  return value.replace(/[\\*()\0]/g, '\\$&');
}

module.exports = { loginHandler };

import java.security.SecureRandom;
import java.util.Base64;

public class SecureTokenGenerator {
    private static final int TOKEN_LENGTH_BYTES = 32;
    private final SecureRandom secureRandom;

    public SecureTokenGenerator() {
        // 使用系统提供的安全随机源
        this.secureRandom = new SecureRandom();
    }

    /**
     * 生成用于密码重置的会话令牌
     * @return Base64编码的安全令牌
     */
    public String generatePasswordResetToken() {
        byte[] tokenBytes = new byte[TOKEN_LENGTH_BYTES];
        // 使用SecureRandom填充随机字节
        secureRandom.nextBytes(tokenBytes);
        // Base64编码以便在URL和数据库中安全存储
        return Base64.getUrlEncoder().withoutPadding().encodeToString(tokenBytes);
    }

    /**
     * 验证令牌是否符合安全要求（示例用途）
     * @param token 待验证的令牌
     * @return 令牌是否有效
     */
    public boolean isValidTokenFormat(String token) {
        if (token == null || token.length() < 32) {
            return false;
        }
        // 检查是否为有效的Base64 URL编码字符
        return token.matches("^[A-Za-z0-9_-]+$");
    }
}

import os
from django.db import connection
from django.http import JsonResponse
from django.views import View
from django.utils.decorators import method_decorator
from django.views.decorators.csrf import csrf_exempt
import json

class UserSearchView(View):
    """用户搜索接口 - 使用Django ORM raw query参数化查询"""

    @method_decorator(csrf_exempt)
    def dispatch(self, *args, **kwargs):
        return super().dispatch(*args, **kwargs)

    def post(self, request):
        try:
            # 解析请求体
            body = json.loads(request.body)
            username = body.get('username', '')
            department = body.get('department', '')

            # 防御1: 输入长度限制 (第17行)
            if len(username) > 50 or len(department) > 50:
                return JsonResponse({'error': 'Invalid input length'}, status=400)

            # 防御2: 字符白名单校验 (第21行)
            import re
            if not re.match(r'^[a-zA-Z0-9_\-\s]*$', username) or \
               not re.match(r'^[a-zA-Z0-9_\-\s]*$', department):
                return JsonResponse({'error': 'Invalid characters'}, status=400)

            # 防御3: 参数化raw query (第27行)
            with connection.cursor() as cursor:
                cursor.execute(
                    "SELECT id, username, email FROM auth_user "
                    "WHERE username LIKE %s AND department LIKE %s",
                    [f'%{username}%', f'%{department}%']
                )
                results = cursor.fetchall()

            # 防御4: 结果集大小限制 (第34行)
            if len(results) > 100:
                results = results[:100]

            # 序列化结果
            user_list = [
                {'id': row[0], 'username': row[1], 'email': row[2]}
                for row in results
            ]

            return JsonResponse({'users': user_list, 'count': len(user_list)})

        except json.JSONDecodeError:
            return JsonResponse({'error': 'Invalid JSON'}, status=400)
        except Exception as e:
            # 防御5: 统一错误处理，不泄露内部信息 (第47行)
            return JsonResponse({'error': 'Internal server error'}, status=500)
